@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class QuickAddController {

    /** The person the claim went to, whether they were added for it, and the claim. */
    public record QuickAddView(PersonView person, boolean added, ClaimView claim) {}

    /** A person's name, as the person form takes it, and a claim's amount, as the claim form takes it. */
    public record QuickAddRequest(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "\\d{1,12}(\\.\\d{1,2})?") String amount) {

        BigDecimal amountValue() {
            return new BigDecimal(amount).setScale(2);
        }
    }

    private final QuickAddService service;
    private final PersonService people;

    public QuickAddController(QuickAddService service, PersonService people) {
        this.service = service;
        this.people = people;
    }

    @PostMapping("/quick-add")
    public QuickAddView add(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid QuickAddRequest request) {
        QuickAddService.QuickAdded done = service.add(sheetId, user, request.name().strip(), request.amountValue());
        return new QuickAddView(PersonView.of(done.person(), people.today(done.person().getSheetId()), people.patronIdsOf(done.person().getId()),
                people.watches(done.person().getId(), user), people.isActive(done.person())), done.added(), ClaimView.of(done.claim()));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Pasted claims: lines of name,amount,date,note (the note may hold commas and may be absent; a blank
 * date is the entry date while set, else the sheet's today), each a DRAFT claim for the person of the name on the sheet (ignoring
 * case and surrounding spaces), added in order exactly as the claim form adds one. A note ending in
 * " #<reference>" gives the claim that external reference (that part is not the note); a reference already
 * on the sheet, or given twice in the paste, compared without regard to case, refuses it. Blank lines are
 * skipped; a paste with no line is refused. It is one change: a line that is refused refuses them all.
 */
@Service
public class ClaimPasteService {

    /** The claim form's amount: up to two decimals, negative only for a correction (which a paste cannot name). */
    private static final Pattern AMOUNT = Pattern.compile("-?\\d{1,12}(\\.\\d{1,2})?");
    private static final int NOTE_MAX = 500;
    private static final int REF_MAX = 200;
    /** A note ending in a space, a hash and the reference. */
    private static final Pattern NOTE_REF = Pattern.compile("(.*) #(.+)", Pattern.DOTALL);

    private record Line(Long personId, BigDecimal amount, LocalDate date, String note, String ref) {}

    private final ClaimService claims;
    private final PersonRepository people;

    public ClaimPasteService(ClaimService claims, PersonRepository people) {
        this.claims = claims;
        this.people = people;
    }

    @Transactional
    public List<Claim> paste(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        for (String raw : text.split("\\R")) {
            if (raw.isBlank()) continue;
            Line line = parse(sheetId, raw);
            if (line.ref() != null && !refs.add(Claim.refKeyOf(line.ref()))) throw new DuplicateClaimRefException();
            lines.add(line);
        }
        if (lines.isEmpty()) throw new ClaimPasteRefusedException();
        List<Claim> added = new ArrayList<>();
        for (Line line : lines) {
            added.add(claims.add(sheetId, user, line.personId(), line.amount(), line.date(), line.note(), null,
                    line.ref()));
        }
        return added;
    }

    private Line parse(String sheetId, String raw) {
        String[] fields = raw.split(",", 4);
        if (fields.length < 3) throw new ClaimPasteRefusedException();
        String name = fields[0].strip();
        String amount = fields[1].strip();
        String date = fields[2].strip();
        String note = fields.length == 4 ? fields[3].strip() : "";
        String ref = null;
        Matcher tail = NOTE_REF.matcher(note);
        if (tail.matches() && !tail.group(2).isBlank()) {
            note = tail.group(1).strip();
            ref = tail.group(2).strip();
        }
        if (name.isEmpty() || !AMOUNT.matcher(amount).matches() || note.length() > NOTE_MAX
                || (ref != null && ref.length() > REF_MAX)) {
            throw new ClaimPasteRefusedException();
        }
        Person person = people.findByNameOrAlias(sheetId, name)
                .orElseThrow(ClaimPasteRefusedException::new);
        LocalDate on;
        try {
            on = date.isEmpty() ? null : LocalDate.parse(date);
        } catch (DateTimeParseException e) {
            throw new ClaimPasteRefusedException();
        }
        return new Line(person.getId(), new BigDecimal(amount).setScale(2), on, note, ref);
    }
}
package net.officefloor.hq.app.rollup;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import net.officefloor.hq.app.sheet.SheetParentRepository;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * The figures of a sheet's descendants (the sheets naming it as their parent, theirs and so on),
 * added up: how many people they have, and each one's due-total and overdue-total as that sheet
 * shows them, and the sheet's own figures as it holds them now. The screen adds the sheet's own figures,
 * as shown (as it holds them now while it is shown as of a date), to make the consolidated ones.
 */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/descendants")
public class ConsolidatedController {

    /** The descendants' figures added up, then the sheet's own; the totals have two decimals. */
    public record DescendantsView(int sheets, int people, String dueTotal, String overdueTotal, int ownPeople,
            String ownDueTotal, String ownOverdueTotal) {}

    private final SheetParentRepository parents;
    private final RollupService rollup;

    public ConsolidatedController(SheetParentRepository parents, RollupService rollup) {
        this.parents = parents;
        this.rollup = rollup;
    }

    @GetMapping("/figures")
    @Transactional(readOnly = true)
    public DescendantsView figures(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        int sheets = 0;
        int people = 0;
        BigDecimal due = BigDecimal.ZERO.setScale(2);
        BigDecimal overdue = BigDecimal.ZERO.setScale(2);
        for (String descendant : parents.descendantsOf(sheetId)) {
            RollupService.Snapshot figures = rollup.current(descendant);
            sheets++;
            people += figures.people().size();
            due = due.add(figures.dueTotal());
            overdue = overdue.add(figures.overdueTotal());
        }
        RollupService.Snapshot own = rollup.current(sheetId);
        return new DescendantsView(sheets, people, due.toPlainString(), overdue.toPlainString(), own.people().size(),
                own.dueTotal().setScale(2).toPlainString(), own.overdueTotal().setScale(2).toPlainString());
    }
}
